// Poll settings are submitted with the initial discussion in a single transaction.
// Server-owned drafts. A single serialized save/publish chain prevents late autosaves
// from overwriting a successful publication. No private text is kept in localStorage.
function draftUuid(){if(crypto.randomUUID)return crypto.randomUUID();const a=crypto.getRandomValues(new Uint8Array(16));a[6]=(a[6]&15)|64;a[8]=(a[8]&63)|128;const h=Array.from(a,x=>x.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)}
