 let id=draftUuid(),revision=0,last='',observed='',dirtyAt=0,chain=Promise.resolve(),stopped=false,conflict=false,publishing=false,loading=false,interval=0;
 const snapshot=()=>JSON.stringify(capture());
 const show=(text)=>{status.textContent=text};
 const current=()=>f('/drafts/'+id);
 async function restore(d){
   if(d.scope!==scope||d.target_id!==target)throw Error('Этот черновик относится к другой публикации.');if(d.result){stopped=true;go(scope==='thread'?threadUrl(d.result):scope==='reply'?'/forum/threads/'+target+'?page='+(d.result.page||1)+'#post-'+d.result.id:scope==='conversation'?conversationUrl(target):conversationUrl(d.result.id));return}
   loading=true;try{const p=d.payload;const mode=el.elements.body_format;mode.value=p.body_format||'plain';mode.dispatchEvent(new Event('change'));el.elements.body.value=p.body||'';if(el.elements.title)el.elements.title.value=p.title||'';if(el.elements.kind)el.elements.kind.value=p.kind||'discussion';if(el.elements.participant_ids)el.elements.participant_ids.value=(p.participant_ids||[]).join(', ');applyExtra(p);await el.attachmentPicker?.restore(p.attachment_ids||[]);id=d.id;revision=d.revision_number;last=observed=snapshot();conflict=false;show('Черновик восстановлен · версия '+revision)}finally{loading=false}
 }
