 async function save(){
   if(conflict)throw Error('Конфликт черновика: загрузите актуальную версию или сохраните отдельную копию.');
   if(el.attachmentPicker?.busy())throw Error('Дождитесь окончания загрузки файлов.');
   const p=capture(),serial=JSON.stringify(p);if(revision&&serial===last)return;
   const d=await f('/drafts/'+id,'PUT',{scope,target_id:target,revision_number:revision,payload:p});revision=d.revision_number;last=serial;show('Сохранено · версия '+revision);
 }
 function autosave(){if(stopped||loading||publishing||conflict||!el.isConnected||el.attachmentPicker?.busy())return;try{const serial=snapshot();if(serial!==observed){observed=serial;dirtyAt=Date.now();show('Изменения не сохранены');return}if(serial!==last&&dirtyAt&&Date.now()-dirtyAt>=2000){dirtyAt=0;queue(save).catch(e=>{conflict=e.status===409;if(!e.status||e.status>=500||e.status===429)dirtyAt=Date.now()+8000;show('Не сохранено: '+e.message)})}}catch(e){show(e.message)}}
 const saveBtn=button('Сохранить черновик',async()=>{try{await queue(save)}catch(e){conflict=e.status===409;show('Не сохранено: '+e.message);throw e}});
