 if(selected){loading=true;void f('/drafts/'+selected).then(d=>{if(snapshot()!==last&&!confirm('Заменить введённый текст сохранённым черновиком?')){conflict=true;return}return restore(d)}).catch(e=>{show('Не удалось открыть черновик: '+e.message);conflict=true}).finally(()=>{loading=false})}
 else void f('/drafts?'+new URLSearchParams({scope,...(target?{target_id:target}:{})})).then(rows=>{if(!el.isConnected||revision||loading||!rows.length)return;const d=rows[0];add(bar,button('Продолжить сохранённый черновик',async()=>{if(snapshot()!==last&&!confirm('Заменить текущий текст?'))return;await queue(()=>restore(d))}));}).catch(()=>{});
