// Bounded line comparison: common prefix/suffix and LCS for moderate changes;
// large edits fall back to a linear removed/added block, never quadratic unbounded work.
function revisionDiff(a,b){const x=a.split('\n'),y=b.split('\n'),out=[];let start=0,endX=x.length,endY=y.length;while(start<endX&&start<endY&&x[start]===y[start]){out.push([' ',x[start]]);start++}while(endX>start&&endY>start&&x[endX-1]===y[endY-1]){endX--;endY--}const m=endX-start,n=endY-start;if(m*n<=100000){const dp=Array.from({length:m+1},()=>new Uint16Array(n+1));for(let i=m-1;i>=0;i--)for(let j=n-1;j>=0;j--)dp[i][j]=x[start+i]===y[start+j]?1+dp[i+1][j+1]:Math.max(dp[i+1][j],dp[i][j+1]);let i=0,j=0;while(i<m||j<n){if(i<m&&j<n&&x[start+i]===y[start+j]){out.push([' ',x[start+i++]]);j++}else if(j<n&&(i===m||dp[i][j+1]>=dp[i+1][j]))out.push(['+',y[start+j++]]);else out.push(['-',x[start+i++]])}}else{for(let i=start;i<endX;i++)out.push(['-',x[i]]);for(let j=start;j<endY;j++)out.push(['+',y[j]])}for(let i=endX;i<x.length;i++)out.push([' ',x[i]]);return out}
