const visibilityChoices=[['public','Все'],['members','Участники'],['private','Только я']];
let profileSettings=null;
function applyPreferences(p){if(!p)return;document.documentElement.dataset.theme=p.theme==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):p.theme;profileSettings=p}
function dateLabel(value){if(!value)return '';const raw=String(value);const stamp=/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(\.\d+)?$/.test(raw)?raw.replace(' ','T')+'Z':raw;const date=new Date(stamp);if(Number.isNaN(date.valueOf()))return raw;try{return new Intl.DateTimeFormat(profileSettings?.locale||'ru-RU',{dateStyle:'medium',timeStyle:'short',timeZone:profileSettings?.timezone||'UTC'}).format(date)}catch{return raw}}
function profilePicture(url,cls){const image=node('img',undefined,cls);image.src=url;image.alt=cls==='profile-cover'?'Обложка профиля':'Аватар';image.loading='lazy';return image}
async function profile(id){const d=await f('/members/'+id+'?page='+page),m=d.member;heading(m.name);const p=panel();if(m.cover_url)add(p,profilePicture(m.cover_url,'profile-cover'));const top=node('div',undefined,'profile-heading');if(m.avatar_url)add(top,profilePicture(m.avatar_url,'profile-avatar'));add(top,node('h2',m.name));add(p,top,node('p','Участник с '+dateLabel(m.created_at)));if(m.bio)add(p,node('div',m.bio,'profile-text'));if(m.location)add(p,node('p','Местоположение: '+m.location));if(m.website){const a=link(m.website,m.website);a.rel='nofollow noopener noreferrer';add(p,a)}if(m.groups?.length)add(p,node('p',m.groups.map(g=>g.name+(Number(g.is_primary)?' (основная)':'')).join(' · ')));for(const field of m.fields||[])add(p,node('p',field.label+': '+field.field_value));if(m.signature)add(p,node('div',m.signature,'profile-signature'));if(m.reputation)add(p,reputationPanel(m.reputation));if(canWrite()&&me.user_id!==id)add(p,await relationshipControls(id));if(canWrite()&&me?.user_id!==id)add(p,link('Написать сообщение','/forum/conversations?to='+id,'button secondary'));if(me?.user_id===id)add(p,link('Редактировать профиль','/forum/account/profile','button secondary'));if(isAdmin()){const controls=node('div',undefined,'actions');for(const [field,label] of [['bio','описание'],['signature','подпись'],['avatar','аватар'],['cover','обложку']])add(controls,button('Очистить '+label,async()=>{if(!confirm('Очистить '+label+'?'))return;await f('/members/'+id+'/moderate-profile','POST',{field});await profile(id)}));add(p,controls)}add(app,p);if(m.activity_visible)add(app,node('h3','Темы пользователя'),list(d.threads,threadUrl),paging(d.threads.length));else add(app,node('p','Активность скрыта.'))}
async function memberDirectory(){heading('Участники');const query=new URLSearchParams(location.search),q=query.get('q')||'',sort=query.get('sort')||'name';const searchForm=node('form');const label=node('label','Имя'),input=node('input');input.name='q';input.value=q;input.maxLength=100;add(label,input);add(searchForm,label,selectField('sort','Сортировка',[['name','По имени'],['newest','Новые участники']],sort),node('button','Найти'));searchForm.addEventListener('submit',e=>{e.preventDefault();go('/forum/members?'+new URLSearchParams(new FormData(searchForm)))});add(app,searchForm);const rows=await f('/members?'+new URLSearchParams({q,sort,page:String(page)}));const p=panel();if(!rows.length)add(p,node('p','Участники не найдены.'));for(const m of rows)add(p,add(node('div',undefined,'entry'),link(m.name,'/forum/members/'+m.id),node('span',dateLabel(m.created_at),'meta')));add(app,p,paging(rows.length))}
function optionalField(name,label,value,max,multiline=false){const l=node('label',label),i=node(multiline?'textarea':'input');i.name=name;i.value=value||'';i.maxLength=max;return add(l,i)}
function checkField(name,label,checked){const l=node('label',label),i=node('input');i.type='checkbox';i.name=name;i.checked=Boolean(checked);return add(l,i)}
function settingsForm(label,submit){const el=node('form'),b=node('button',label);b.type='submit';el.addEventListener('submit',e=>{e.preventDefault();b.disabled=true;run(async()=>{try{await submit(el)}finally{b.disabled=false}})});return [el,b]}
