async function conversationSettingsPage(){app.replaceChildren();heading('Настройки переписок');if(!canWrite()){add(app,link('Войти','/forum/login'));return}const d=await f('/conversation-settings');const [el,save]=settingsForm('Сохранить настройки переписок',async el=>{await f('/conversation-settings','PUT',{incoming:el.elements.incoming.value});say('Настройки сохранены.')});add(el,selectField('incoming','Новые переписки и приглашения',[['members','От участников форума'],['none','Ни от кого']],d.incoming),save);add(app,el,link('← Переписки','/forum/conversations'));const p=panel();add(p,node('h3','Заблокированные участники'));for(const b of d.blocked)add(p,add(node('div',undefined,'entry'),node('span',b.name),button('Разблокировать',async()=>{await f('/conversation-blocks/'+b.id,'PUT',{enabled:false});await conversationSettingsPage()})));const block=form([['id','UUID участника']],'Заблокировать',async data=>{await f('/conversation-blocks/'+data.id,'PUT',{enabled:true});await conversationSettingsPage()});add(p,block);add(app,p)}
async function conversationReportsPage(){app.replaceChildren();heading('Жалобы на личные сообщения');if(!isAdmin()){add(app,node('p','Требуются права системного администратора.'));return}const rows=await f('/conversation-reports?page='+page);const p=panel();for(const r of rows){const row=node('div',undefined,'entry'),detail=node('div');add(row,node('span',`${r.status} · ${conversationDate(r.created_at)}`),button('Рассмотреть жалобу',async()=>{const d=await f('/conversation-reports/'+r.id);detail.replaceChildren(node('p','Причина: '+d.reason),node('div',d.body_snapshot,'profile-text'));if(d.status==='open')for(const [status,label] of [['resolved','Решена'],['dismissed','Отклонить']])add(detail,button(label,async()=>{await f('/conversation-reports/'+r.id,'PUT',{status});await conversationReportsPage()}))}),detail);add(p,row)}if(!rows.length)add(p,node('p','Нет жалоб.'));add(app,p,paging(rows.length))}
function conversationNotificationPanel(d){if(!canWrite())return null;const p=panel();add(p,node('h3',`Новые личные сообщения: ${d.conversation_unread}`),link('Все переписки','/forum/conversations'));for(const item of d.conversations||[])add(p,add(node('div',undefined,'entry'),link(item.title,conversationUrl(item.id)),node('span',`${item.unread} новых`,'meta')));return p}

const reactionLabels={like:'Нравится',helpful:'Полезно',celebrate:'Отлично'};
const achievementLabels={first_post:'Первый шаг',active_member:'Активный участник',topic_author:'Автор обсуждений',helpful_member:'Полезный участник',veteran:'Ветеран сообщества'};
function reactionSummary(p){return Object.entries(reactionLabels).map(([k,v])=>`${v}: ${Number(p.reactions?.[k]||0)}`).join(' · ')}
function reactionControls(p,refresh){const wrap=node('div',undefined,'actions reaction-controls');for(const [type,label] of Object.entries(reactionLabels)){const b=button(label,async()=>{await f(`/posts/${p.id}/reaction`,'PUT',{enabled:p.my_reaction!==type,type});await refresh()});b.setAttribute('aria-pressed',String(p.my_reaction===type));add(wrap,b)}if(p.my_reaction)add(wrap,button('Убрать реакцию',async()=>{await f(`/posts/${p.id}/reaction`,'PUT',{enabled:false});await refresh()}));return wrap}
function reputationPanel(s){const box=node('div',undefined,'reputation');add(box,node('h3','Репутация'),node('p',`${s.reputation} баллов · ${s.reactions} реакций · ${s.threads} тем · ${s.posts} сообщений`),node('p','Учитываются только общедоступные обсуждения.','meta'));const badges=node('div',undefined,'actions');for(const code of s.achievements||[])add(badges,node('span',achievementLabels[code]||code,'thread-tag'));add(box,badges);return box}
async function relationshipControls(id){const d=await f('/members/'+id+'/relationship'),wrap=node('div',undefined,'actions');for(const [kind,yes,no] of [['follow','Подписаться на участника','Отписаться от участника'],['ignore','Игнорировать','Не игнорировать']])add(wrap,button(d[kind]?no:yes,async()=>{await f('/members/'+id+'/relationship','PUT',{kind,enabled:!d[kind]});await profile(id)}));return wrap}
async function activityPage(){heading('Активность сообщества');const scope=new URLSearchParams(location.search).get('scope')||'all';const nav=node('div',undefined,'actions');add(nav,link('Вся активность','/forum/activity','button secondary'),link('Рейтинг','/forum/leaderboard','button secondary'));if(me)add(nav,link('Моя активность','/forum/activity?scope=mine','button secondary'),link('Мои подписки','/forum/activity?scope=following','button secondary'));if(canWrite())add(nav,link('Участники и игнорирование','/forum/member-relations','button secondary'));add(app,nav);const rows=await f('/activity?'+new URLSearchParams({scope,page:String(page)}));const box=panel();if(!rows.length)add(box,node('p','Нет доступной активности.'));for(const item of rows){const row=node('div',undefined,'entry'),main=node('div');add(main,link(item.author,'/forum/members/'+item.author_id),node('span',' · '+dateLabel(item.created_at),'meta'),node('p',Number(item.ordinal)===1?'Начал обсуждение':'Опубликовал сообщение'),link(item.title,`/forum/threads/${item.thread_id}?page=${Math.ceil(Number(item.ordinal)/25)}#post-${item.post_id}`));add(box,add(row,main))}add(app,box,paging(rows.length))}
async function leaderboardPage(){heading('Рейтинг участников');add(app,link('Активность','/forum/activity'),node('p','Баллы начисляются за реакции в общедоступных обсуждениях. Собственные реакции не учитываются.','meta'));const rows=await f('/leaderboard?page='+page),box=panel();if(!rows.length)add(box,node('p','Пока нет участников с репутацией.'));for(const [i,m] of rows.entries())add(box,add(node('div',undefined,'entry'),node('span',String((page-1)*25+i+1)),link(m.name,'/forum/members/'+m.id),node('span',`${m.reputation} баллов · ${m.reactions} реакций`)));add(app,box,paging(rows.length))}
async function relationsPage(){heading('Подписки на участников и игнорирование');if(!canWrite()){add(app,link('Войти','/forum/login'));return}const kind=new URLSearchParams(location.search).get('kind')||'follow';add(app,link('Подписки','/forum/member-relations?kind=follow','button secondary'),link('Игнорируемые','/forum/member-relations?kind=ignore','button secondary'));const rows=await f('/member-relations?'+new URLSearchParams({kind,page:String(page)})),box=panel();if(!rows.length)add(box,node('p','Список пуст.'));for(const row of rows)add(box,add(node('div',undefined,'entry'),row.name?link(row.name,'/forum/members/'+row.id):node('span','Профиль недоступен'),button(kind==='follow'?'Отписаться':'Не игнорировать',async()=>{await f('/members/'+row.id+'/relationship','PUT',{kind,enabled:false});await relationsPage()})));add(app,box,paging(rows.length))}
async function achievementAdmin(){const box=panel();add(box,node('h3','Достижения'),node('p','Пороги проверяются по текущим публичным данным; при снижении показателя достижение исчезает.','meta'));for(const r of await f('/achievement-rules')){const [el,save]=settingsForm('Сохранить '+achievementLabels[r.code],async el=>{await f('/achievement-rules/'+r.code,'PUT',{threshold:Number(el.elements.threshold.value),enabled:el.elements.enabled.checked});say('Правило сохранено.')});const input=node('input');input.type='number';input.name='threshold';input.min='1';input.max='1000000';input.required=true;input.value=String(r.threshold);const check=node('input');check.type='checkbox';check.name='enabled';check.checked=Number(r.enabled)===1;add(el,add(node('label',achievementLabels[r.code]+' — порог'),input),add(node('label','Включено'),check),save);add(box,el)}return box}
async function init(){applyPreferences({theme:'system',locale:'ru-RU',timezone:'UTC'});matchMedia('(prefers-color-scheme: light)').addEventListener('change',()=>{if(profileSettings?.theme==='system')applyPreferences(profileSettings)});try{me=await api('/auth/me')}catch{}const s=document.getElementById('session');if(me){try{applyPreferences((await f('/account/profile')).preferences)}catch{}add(s,link(me.user?.name||'Участник','/forum/account'),button('Выйти',async()=>{await api('/auth/logout','POST');go('/forum')}));document.getElementById('conversations').hidden=!canWrite();document.getElementById('drafts').hidden=!canWrite();document.getElementById('unread').hidden=false;document.getElementById('notifications').hidden=false;void notificationBadge();setInterval(()=>{if(!document.hidden)void notificationBadge()},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)void notificationBadge()});document.getElementById('watches').hidden=!canWrite();document.getElementById('manage').hidden=!canModerate()}else add(s,link('Вход','/forum/login'));const path=location.pathname.replace(/\/$/,'');let m;if(path===''||path==='/forum')await home();else if((m=path.match(/^\/forum\/boards\/([a-f0-9-]+)$/)))await board(m[1]);else if((m=path.match(/^\/forum\/threads\/([a-f0-9-]+)$/)))await thread(m[1]);else if(path==='/forum/members')await memberDirectory();else if(['/forum/account/profile','/forum/account/preferences','/forum/account/privacy'].includes(path))await profileAccount();else if(path==='/forum/search')await search();else if(path==='/forum/latest')await latest();else if(path==='/forum/activity')await activityPage();else if(path==='/forum/drafts')await draftsPage();else if(path==='/forum/questions')await questionsPage();else if(path==='/forum/leaderboard')await leaderboardPage();else if(path==='/forum/member-relations')await relationsPage();else if(path==='/forum/unread')await unread();else if(path==='/forum/notifications')await notifications();else if(path==='/forum/conversations')await conversationsPage();else if((m=path.match(/^\/forum\/conversations\/([a-f0-9-]+)$/)))await conversationPage(m[1]);else if(path==='/forum/conversation-settings')await conversationSettingsPage();else if(path==='/forum/conversation-reports')await conversationReportsPage();else if((m=path.match(/^\/forum\/members\/([a-f0-9-]+)$/)))await profile(m[1]);else if(path==='/forum/login')auth();else if(path==='/forum/register')auth(true);else if(path==='/forum/resend-email')mailPage(false);else if(path==='/forum/forgot-password')mailPage(true);else if(path==='/forum/verify-email')tokenPage(false);else if(path==='/forum/reset-password')tokenPage(true);else if(path==='/forum/account'||path==='/forum/account/security'||path==='/forum/account/sessions')await account();else if(path==='/forum/watches')await watches();else if(path==='/forum/unsubscribe')unsubscribePage();else if(path==='/forum/manage')await manage();else heading('Страница не найдена')}
